diff --git a/src/recovery.ts b/src/recovery.ts
index c91b345..74105db 100644
--- a/src/recovery.ts
+++ b/src/recovery.ts
@@ -1,6 +1,28 @@
+function asRecord(value: unknown): Record<string, unknown> | null {
+  if (typeof value !== "object" || value === null || Array.isArray(value)) {
+    return null;
+  }
+  return value as Record<string, unknown>;
+}
+
+function nonEmptyString(value: unknown): string | null {
+  return typeof value === "string" && value.length > 0 ? value : null;
+}
+
+function nonNegativeInt(value: unknown): number | null {
+  return typeof value === "number" && Number.isInteger(value) && value >= 0 ? value : null;
+}
+
+function positiveInt(value: unknown): number | null {
+  return typeof value === "number" && Number.isInteger(value) && value > 0 ? value : null;
+}
+
 export function reclaimCause(meta: unknown): string | null {
-  void meta;
-  throw new Error("not implemented");
+  const rec = asRecord(meta);
+  if (rec === null) {
+    return null;
+  }
+  return nonEmptyString(rec.cause);
 }

 export function recoveryBudget(input: unknown): {
@@ -9,11 +31,32 @@ export function recoveryBudget(input: unknown): {
   remaining: number;
   exhausted: boolean;
 } {
-  void input;
-  throw new Error("not implemented");
+  const rec = asRecord(input);
+  const attempt = rec === null ? 0 : (nonNegativeInt(rec.attempt) ?? 0);
+  const maxAttempts = rec === null ? 0 : (positiveInt(rec.max_attempts) ?? 0);
+  const remaining = Math.max(0, maxAttempts - attempt);
+  return {
+    attempt,
+    max_attempts: maxAttempts,
+    remaining,
+    exhausted: attempt >= maxAttempts,
+  };
 }

 export function summarizeReclaims(events: unknown): { requeues: number; causes: string[] } {
-  void events;
-  throw new Error("not implemented");
+  if (!Array.isArray(events)) {
+    return { requeues: 0, causes: [] };
+  }
+  const causes: string[] = [];
+  for (const event of events) {
+    const rec = asRecord(event);
+    if (rec === null || rec.kind !== "claim.reoffer") {
+      continue;
+    }
+    const cause = reclaimCause(rec.meta);
+    if (cause !== null) {
+      causes.push(cause);
+    }
+  }
+  return { requeues: causes.length, causes };
 }

